/bin/zsh -lc 'JSHELL_CP="sm-shop-model/target/classes:$(find "$HOME/.m2/repository" -name '"'*.jar' -print | paste -sd: -)\"; jshell --class-path \""'$JSHELL_CP" <<'"'EOF'
import javax.validation.Validation;
import com.salesmanager.shop.model.catalog.manufacturer.PersistableManufacturer;
var validator = Validation.buildDefaultValidatorFactory().getValidator();
var invalid = new PersistableManufacturer();
invalid.setWebsite(\"www.example.com\");
var invalidViolations = validator.validate(invalid);
System.out.println(\"invalid violations=\" + invalidViolations.size());
var optional = new PersistableManufacturer();
var optionalViolations = validator.validate(optional);
System.out.println(\"null violations=\" + optionalViolations.size());
EOF"

/bin/zsh -lc './mvnw -q -pl sm-shop dependency:build-classpath -Dmdep.outputFile=/tmp/shopizer-validation-classpath && VALIDATION_CP="sm-shop-model/target/classes:$(cat /tmp/shopizer-validation-classpath)"; jshell --class-path "$VALIDATION_CP" <<'"'EOF'
import javax.validation.Validation;
import com.salesmanager.shop.model.catalog.manufacturer.PersistableManufacturer;
var validator = Validation.buildDefaultValidatorFactory().getValidator();
var invalid = new PersistableManufacturer();
invalid.setWebsite(\"www.example.com\");
System.out.println(\"invalid violations=\" + validator.validate(invalid).size());
var optional = new PersistableManufacturer();
System.out.println(\"null violations=\" + validator.validate(optional).size());
EOF"

